"""gcs-allowlist · PreToolUse sobre las tools MCP del server de Cloud Storage.

Allowlist, no denylist: pasan solo las tres tools de lectura que usa el toolkit, y solo
contra el bucket de prueba. Todo lo demás se veta, incluida cualquier tool nueva que
traiga la próxima versión del server, hasta que alguien la revise y la agregue acá.

Es la capa de arriba, no la garantía. Debajo están el modo del server (sin
--enable-destructive-tools no existen delete_object ni move_object) y, la que garantiza,
la credencial: la service account solo tiene roles/storage.objectViewer sobre el bucket.

El nombre de la tool cambia al empaquetar:
    mcp__gcs__<tool>   ->   mcp__plugin_gcsgrep-sdd_gcs__<tool>
Este script acepta los dos. Un matcher que no matchea no avisa: simplemente no veta.

Sale 0 para dejar pasar y 2 para vetar (el stderr le llega al agente).
"""
import json
import os
import re
import sys

PERMITIDAS = {"list_objects", "read_object_metadata", "read_object_content"}
PREFIJO = re.compile(r"^mcp__(?:plugin_gcsgrep-sdd_)?gcs__(?P<tool>[A-Za-z0-9_]+)$")


def bucket_permitido():
    # Proyecto: GCSGREP_BUCKET en el entorno. Plugin: la opción `bucket` del userConfig.
    return (os.environ.get("GCSGREP_BUCKET")
            or os.environ.get("CLAUDE_PLUGIN_OPTION_BUCKET")
            or "").strip()


def vetar(motivo):
    print("gcs-allowlist: " + motivo, file=sys.stderr)
    return 2


def decidir(evento):
    nombre = evento.get("tool_name")
    if not isinstance(nombre, str):
        return vetar("el evento no trae tool_name; bloqueo por las dudas.")
    m = PREFIJO.match(nombre)
    if not m:
        return vetar(nombre + " no es una tool del server gcs que este hook conozca. "
                     "Si el matcher la mandó acá, revisá el nombre del server.")
    tool = m.group("tool")
    if tool not in PERMITIDAS:
        return vetar(tool + " no está en la allowlist (solo list_objects, "
                     "read_object_metadata y read_object_content). El toolkit lee el "
                     "bucket de prueba, no escribe ni administra: si hace falta un objeto "
                     "nuevo, lo sube una persona con su propia cuenta.")
    esperado = bucket_permitido()
    if not esperado:
        return vetar("no sé cuál es el bucket de prueba: definí GCSGREP_BUCKET (o la "
                     "opción bucket del plugin). Sin eso no dejo leer ningún bucket.")
    entrada = evento.get("tool_input")
    if not isinstance(entrada, dict):
        return vetar("el evento no trae tool_input; bloqueo por las dudas.")
    bucket = entrada.get("bucket_name")
    if bucket != esperado:
        return vetar("%s sobre el bucket %r: este toolkit solo lee %r, el bucket de "
                     "prueba con objetos sintéticos." % (tool, bucket, esperado))
    return 0


def main():
    # En Windows, con stderr a un pipe, Python escribe en cp1252 y Claude Code lee UTF-8:
    # el agente recibía "est�" en vez de "está".
    sys.stderr.reconfigure(encoding="utf-8")
    try:
        evento = json.load(sys.stdin)
    except (ValueError, UnicodeDecodeError):
        return vetar("no pude leer el evento JSON; bloqueo por las dudas.")
    if not isinstance(evento, dict):
        return vetar("el evento no es un objeto JSON; bloqueo por las dudas.")
    return decidir(evento)


if __name__ == "__main__":
    sys.exit(main())

"""Literal line matching for gcsgrep."""


def find_matches(lines, pattern: str, ignore_case: bool = False):
    """Yield ``(line_number, line)`` for every matching line."""
    needle = pattern.casefold() if ignore_case else pattern
    for number, line in enumerate(lines, start=1):
        haystack = line.casefold() if ignore_case else line
        if needle in haystack:
            yield number, line

"""Google Cloud Storage access and streaming scan primitives."""

from __future__ import annotations

from dataclasses import dataclass
from itertools import chain
from typing import Callable, Iterable

from .matcher import find_matches

SAMPLE_SIZE = 8192
CHUNK_SIZE = 64 * 1024


class GcsGrepError(Exception):
    """Expected operational error shown without a traceback."""


class CostLimitReached(GcsGrepError):
    """The configured object or byte limit was reached."""


@dataclass
class ScanResult:
    scanned_objects: int = 0
    matched: bool = False
    had_errors: bool = False


def parse_gs_uri(uri: str) -> tuple[str, str]:
    """Return bucket and exact object-name prefix from a gs:// URI."""
    if not uri.startswith("gs://"):
        raise GcsGrepError("la ubicación debe comenzar con gs://")

    remainder = uri[5:]
    if not remainder or remainder.startswith("/"):
        raise GcsGrepError("la ubicación debe incluir un bucket válido")

    bucket, separator, prefix = remainder.partition("/")
    if not bucket or any(char.isspace() for char in bucket):
        raise GcsGrepError("el nombre del bucket no es válido")

    return bucket, prefix if separator else ""


def create_storage_client():
    """Create the official GCS client using Application Default Credentials."""
    try:
        from google.cloud import storage
    except ImportError as exc:  # pragma: no cover - exercised in installation errors
        raise GcsGrepError(
            "falta la dependencia google-cloud-storage; instalá el proyecto con pip"
        ) from exc

    try:
        return storage.Client()
    except Exception as exc:  # pragma: no cover - depends on local credentials
        raise GcsGrepError(f"no se pudieron cargar las credenciales de GCP: {exc}") from exc


def _decode_line(raw: bytes) -> str:
    return raw.removesuffix(b"\r").decode("utf-8")


def _iter_utf8_lines(stream, first_chunk: bytes) -> Iterable[str]:
    """Split a stream into lines and decode each one without buffering the object.

    Decoding line by line makes a failed object deterministic (FR-6): every line
    before the first invalid one is yielded, and none after it.
    """
    pending = b""

    for chunk in chain(
        (first_chunk,),
        iter(lambda: stream.read(CHUNK_SIZE), b""),
    ):
        pending += chunk
        *lines, pending = pending.split(b"\n")
        for line in lines:
            yield _decode_line(line)

    if pending:
        yield _decode_line(pending)


def _scan_blob(
    blob,
    pattern: str,
    ignore_case: bool,
    include_line_numbers: bool,
    on_match: Callable[[str, int, str], None],
) -> bool:
    name = getattr(blob, "name", "")
    if name.lower().endswith(".gz"):
        return False

    stream = blob.open("rb")
    try:
        first_chunk = stream.read(SAMPLE_SIZE)
        if b"\x00" in first_chunk:
            return False

        found = False
        lines = _iter_utf8_lines(stream, first_chunk)
        for line_number, line in find_matches(lines, pattern, ignore_case):
            found = True
            on_match(name, line_number if include_line_numbers else 0, line)
        return found
    finally:
        stream.close()


def scan(
    client,
    location: str,
    pattern: str,
    *,
    ignore_case: bool = False,
    include_line_numbers: bool = False,
    max_objects: int = 1000,
    max_bytes: int = 1024**3,
    on_match: Callable[[str, int, str], None] | None = None,
    on_error: Callable[[str, Exception], None] | None = None,
    on_progress: Callable[[int], None] | None = None,
    progress_every: int = 100,
) -> ScanResult:
    """Scan objects below ``location`` using an injected GCS client."""
    bucket_name, prefix = parse_gs_uri(location)
    bucket = client.bucket(bucket_name)
    on_match = on_match or (lambda _name, _line, _text: None)
    on_error = on_error or (lambda _name, _error: None)
    result = ScanResult()
    bytes_considered = 0

    try:
        blobs = bucket.list_blobs(prefix=prefix)
        for blob in blobs:
            result.scanned_objects += 1
            if result.scanned_objects > max_objects:
                raise CostLimitReached(
                    f"límite de seguridad alcanzado: máximo {max_objects} objetos"
                )

            size = getattr(blob, "size", None) or 0
            if bytes_considered + size > max_bytes:
                raise CostLimitReached(
                    f"límite de seguridad alcanzado: máximo {max_bytes} bytes"
                )
            bytes_considered += size

            try:
                object_uri = f"gs://{bucket_name}/{getattr(blob, 'name', '')}"

                def emit_match(_name, line_number, text):
                    on_match(object_uri, line_number, text)

                if _scan_blob(
                    blob,
                    pattern,
                    ignore_case,
                    include_line_numbers,
                    emit_match,
                ):
                    result.matched = True
            except Exception as exc:
                result.had_errors = True
                on_error(
                    f"gs://{bucket_name}/{getattr(blob, 'name', '<objeto desconocido>')}",
                    exc,
                )

            if progress_every and result.scanned_objects % progress_every == 0:
                if on_progress:
                    on_progress(result.scanned_objects)
    except CostLimitReached:
        raise
    except Exception as exc:
        raise GcsGrepError(f"no se pudo enumerar gs://{bucket_name}/{prefix}: {exc}") from exc

    return result
